Definition crs_segB_post (sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (A own : Z) (junkB : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
    ms' = MS (mkR (Z_to_bv 64 P_CRS_RET2) sp gp tp t0 t1 t2 s0 (Z_to_bv 64 A) (Z_to_bv 64 (A + 48)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_MAKE_SHARED_IMPL) fc None m' (seg_rom rsegs)
    /\ munch [(A, A + 48)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ rw_cells rsegs m' A (SvcHdrCells (mkSVC VP_SSVC 0 0 own 0 0))
    /\ rw_cells rsegs m' (A + 48) [CB 16 (skipn 48 junkB)].

Lemma crs_segB : forall sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (A own : Z) (junkB : list byte),
  rw_cells rsegs m A [CB 64 junkB] -> 0 < A -> A + 64 <= 2^64 -> 0 <= own < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (crs_segB_post sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s0 (Z_to_bv 64 own) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc A own junkB m)
    (MS (mkR (Z_to_bv 64 P_CRS_RET1) sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 own) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CRS_RET1) fc None m (seg_rom rsegs)).
